import seaborn as sns

df["age"].hist(bins=30)                               # distribution shape
sns.boxplot(x=df["income"])                           # spot outliers
sns.scatterplot(x="sqft", y="price", data=df)         # relationship between two vars
sns.heatmap(df.corr(numeric_only=True), annot=True)   # correlation matrix
df["city"].value_counts().plot(kind="bar")            # category frequencies

import pandas as pd
import numpy as np

rng = np.random.default_rng(42)
n = 300

df = pd.DataFrame({
    "sqft": rng.normal(1500, 400, n).clip(400, 3500),
    "bedrooms": rng.integers(1, 6, n),
    "age": rng.integers(0, 60, n),
})
# price is REALLY a function of sqft + noise; age is noise
df["price"] = 80 * df["sqft"] + rng.normal(0, 15000, n)

# 1) Univariate: describe + quick shape checks
