# sqft vs price ~0.99 -> the signal; age vs price ~0 -> noise

# 3) Categorical analysis: average price by bedrooms
print(df.groupby("bedrooms")["price"].mean().round(0))

# 4) Sanity filter: impossible values
print("negative prices:", (df["price"] < 0).sum())

# 5) Split-feature check: does price behave differently across age groups?
df["age_bucket"] = pd.cut(df["age"], bins=[0, 20, 40, 100])
print(df.groupby("age_bucket", observed=True)["price"].mean().round(0))
